// Pulls the useful fields out of one raw Google Workspace Drive audit-log entry and tags whether
// it's an access-relevant event (view/download/print) worth counting toward this hour's totals.
// Also tries to recognize the firm's own matter numbering convention in the file name so the
// eventual alert can say WHICH MATTER was touched, not just which file.
const item = $json;
const actorEmail = (item.actor && item.actor.email) || 'unknown@unknown';
const event = (item.events && item.events[0]) || {};
const eventType = event.name || 'unknown';
const params = event.parameters || [];
function getParam(paramName) {
  const p = params.find(p => p.name === paramName);
  if (!p) return '';
  return p.value || (p.multiValue && p.multiValue.join(', ')) || '';
}
const docTitle = getParam('doc_title') || '(untitled document)';
const timestamp = (item.id && item.id.time) || '';

// ⚙️ Edit this to match your firm's actual matter numbering convention.
const MATTER_REF_PATTERN = /\d{4}-[A-Z]{2}-\d{3}/;
const matterMatch = docTitle.match(MATTER_REF_PATTERN);
const matterRef = matterMatch ? matterMatch[0] : 'Unmatched / General Files';

const ACCESS_EVENTS = ['view', 'download', 'print'];
const DOWNLOAD_EVENTS = ['download', 'print'];

return { json: {
  actor_email: actorEmail,
  event_type: eventType,
  doc_title: docTitle,
  matter_ref: matterRef,
  timestamp,
  is_access_event: ACCESS_EVENTS.includes(eventType),
  is_download_event: DOWNLOAD_EVENTS.includes(eventType),
} };

// Groups this hour's access events by user, so each user's total volume can be checked against
// the firm's thresholds in one place, with the matters and file names they touched attached.
const items = $input.all().map(i => i.json);
const byUser = {};
for (const it of items) {
  if (!byUser[it.actor_email]) {
    byUser[it.actor_email] = { actor_email: it.actor_email, access_count: 0, download_count: 0, matterCounts: {}, sampleTitles: [] };
  }
  const u = byUser[it.actor_email];
  u.access_count += 1;
  if (it.is_download_event) u.download_count += 1;
  u.matterCounts[it.matter_ref] = (u.matterCounts[it.matter_ref] || 0) + 1;
  if (u.sampleTitles.length < 5 && !u.sampleTitles.includes(it.doc_title)) u.sampleTitles.push(it.doc_title);
}
return Object.values(byUser).map(u => {
  const topMatters = Object.entries(u.matterCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([ref, count]) => `${ref} (${count})`);
  return { json: {
    actor_email: u.actor_email,
    access_count: u.access_count,
    download_count: u.download_count,
    top_matters: topMatters,
    sample_titles: u.sampleTitles,
  } };
});

// Compares each user's hourly totals against the firm's thresholds, and enforces a cooldown so the
// same user doesn't re-trigger an email every single hour while they're still above the line --
// tracked via n8n's own workflow static data, keyed by user, same pattern used elsewhere in this
// catalog for escalation dedupe.
const user = $json;
const BULK_DOWNLOAD_THRESHOLD = Number($vars.BULK_DOWNLOAD_THRESHOLD || 15);
const ACCESS_BURST_THRESHOLD = Number($vars.ACCESS_BURST_THRESHOLD || 40);
const ALERT_COOLDOWN_HOURS = Number($vars.ALERT_COOLDOWN_HOURS || 6);

const overDownloadThreshold = user.download_count >= BULK_DOWNLOAD_THRESHOLD;
const overAccessThreshold = user.access_count >= ACCESS_BURST_THRESHOLD;
const isAnomalous = overDownloadThreshold || overAccessThreshold;

const staticData = $getWorkflowStaticData('global');
if (!staticData.lastAlertedAt) staticData.lastAlertedAt = {};
const lastAlertedAt = staticData.lastAlertedAt[user.actor_email];
const cooldownMs = ALERT_COOLDOWN_HOURS * 60 * 60 * 1000;
const now = Date.now();
const offCooldown = !lastAlertedAt || (now - new Date(lastAlertedAt).getTime()) >= cooldownMs;

const needsAlert = isAnomalous && offCooldown;
if (needsAlert) {
  staticData.lastAlertedAt[user.actor_email] = new Date(now).toISOString();
}

return { json: {
  ...user,
  over_download_threshold: overDownloadThreshold,
  over_access_threshold: overAccessThreshold,
  needs_alert: needsAlert,
} };

// Builds a plain-language security alert email for the firm admin -- what was flagged, why, which
// matters/files were involved, and an explicit reminder this is metadata only, not a content review.
const u = $json;
const FIRM_NAME = $vars.FIRM_NAME || 'the firm';

const reasonParts = [];
if (u.over_download_threshold) reasonParts.push(`${u.download_count} downloads/prints in the last hour`);
if (u.over_access_threshold) reasonParts.push(`${u.access_count} total file accesses in the last hour`);
const reason = reasonParts.join(' and ');

const mattersList = u.top_matters.length ? u.top_matters.join(', ') : 'no matter reference recognized in the file names';
const titlesList = (u.sample_titles || []).map(t => `<li>${t}</li>`).join('');

const subject = `Unusual file access detected — ${u.actor_email}`;
const html = `<p>${FIRM_NAME}'s security watchdog noticed unusual Google Drive activity in the last hour.</p>` +
  `<p><strong>User:</strong> ${u.actor_email}<br/>` +
  `<strong>Why flagged:</strong> ${reason}<br/>` +
  `<strong>Matters touched (top 5):</strong> ${mattersList}</p>` +
  `<p><strong>Sample file names accessed:</strong></p><ul>${titlesList}</ul>` +
  `<p>This alert is based on file names and access metadata only — no document contents were read or analyzed. ` +
  `If this doesn't match the user's normal work pattern, confirm with them directly and consider reviewing the account for compromise.</p>`;

return { json: {
  ...u,
  recipient: $vars.SECURITY_ALERT_EMAIL || $vars.FIRM_EMAIL,
  subject,
  message: `${reason} for ${u.actor_email}. Matters touched: ${mattersList}.`,
  email_html: html,
} };

// Same normalization as the hourly branch -- pulls out user, event type, file name/matter reference --
// just applied to a week's worth of events instead of an hour's.
const item = $json;
const actorEmail = (item.actor && item.actor.email) || 'unknown@unknown';
const event = (item.events && item.events[0]) || {};
const eventType = event.name || 'unknown';
const params = event.parameters || [];
function getParam(paramName) {
  const p = params.find(p => p.name === paramName);
  if (!p) return '';
  return p.value || (p.multiValue && p.multiValue.join(', ')) || '';
}
const docTitle = getParam('doc_title') || '(untitled document)';

const MATTER_REF_PATTERN = /\d{4}-[A-Z]{2}-\d{3}/;
const matterMatch = docTitle.match(MATTER_REF_PATTERN);
const matterRef = matterMatch ? matterMatch[0] : 'Unmatched / General Files';

const ACCESS_EVENTS = ['view', 'download', 'print'];
const DOWNLOAD_EVENTS = ['download', 'print'];

return { json: {
  actor_email: actorEmail,
  event_type: eventType,
  doc_title: docTitle,
  matter_ref: matterRef,
  is_access_event: ACCESS_EVENTS.includes(eventType),
  is_download_event: DOWNLOAD_EVENTS.includes(eventType),
} };

// Rolls the whole week up into one firm-wide summary: total events, total users active, and the
// top 10 users by access volume -- always produces exactly one output item, even if the firm had
// zero Drive activity this week.
const items = $input.all().map(i => i.json);
const byUser = {};
for (const it of items) {
  if (!byUser[it.actor_email]) byUser[it.actor_email] = { actor_email: it.actor_email, access_count: 0, download_count: 0, matters: new Set() };
  const u = byUser[it.actor_email];
  u.access_count += 1;
  if (it.is_download_event) u.download_count += 1;
  u.matters.add(it.matter_ref);
}
const users = Object.values(byUser).map(u => ({
  actor_email: u.actor_email,
  access_count: u.access_count,
  download_count: u.download_count,
  matters_touched: u.matters.size,
})).sort((a, b) => b.access_count - a.access_count);

return [{ json: {
  total_events: items.length,
  total_users: users.length,
  top_users: users.slice(0, 10),
} }];

// Builds the weekly digest email. Explicitly handles the zero-activity week rather than sending a
// blank or malformed table -- same 'never go silent' philosophy used for other periodic digests in
// this catalog.
const data = $json;
const FIRM_NAME = $vars.FIRM_NAME || 'the firm';
let rows;
if (!data.top_users || data.top_users.length === 0) {
  rows = '<tr><td colspan="4">No Google Drive activity logged this week.</td></tr>';
} else {
  rows = data.top_users.map(u => `<tr><td>${u.actor_email}</td><td>${u.access_count}</td><td>${u.download_count}</td><td>${u.matters_touched}</td></tr>`).join('');
}
const subject = `Weekly Drive access pattern summary — ${data.total_events} events`;
const html = `<p>Here's ${FIRM_NAME}'s weekly Google Drive access summary — for visibility, not necessarily anything alarming.</p>` +
  `<table border="1" cellpadding="6" style="border-collapse:collapse;">` +
  `<tr><th>User</th><th>Total accesses</th><th>Downloads/prints</th><th>Matters touched</th></tr>${rows}</table>` +
  `<p>Total events this week: ${data.total_events} across ${data.total_users} user(s). This is metadata only — no document contents were reviewed.</p>`;

return [{ json: {
  ...data,
  recipient: $vars.SECURITY_ALERT_EMAIL || $vars.FIRM_EMAIL,
  subject,
  message: `${data.total_events} Drive access events across ${data.total_users} user(s) this week.`,
  email_html: html,
} }];
